-- P1b: PRIME dictionary expansion (data) + matcher upgrade + admin tools. Idempotent.
-- Data: ~8059 phrases (services, cities and neighborhoods, sections, intents) in Egyptian colloquial, Franco-Arab and common misspellings. INSERT ... ON CONFLICT DO NOTHING.
-- prime_answer (CREATE OR REPLACE): also matches geo_areas names (mapped to their city), services.name_en, and sections (lists their services). Still read-only; only write is the unanswered log.
-- 4 admin functions (admin or services.manage only; refused for everyone else). They contain GRANT EXECUTE TO authenticated, which needs Ahmed's ok.
